{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C69"],
      "claim": "Absolute oral bioavailability of zalcitabine was 80% (range 54–127%) in patients with advanced HIV infection, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Mean absolute bioavailability of lamivudine oral solution was 86–88% versus IV in HIV patients, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C72"],
      "claim": "Absolute oral bioavailability of niraparib was 72.7% (90% CI 61.69–83.40) after a 300 mg oral dose versus IV, well above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer evidence molecules show oral bioavailability values above 20%, mostly 34–100%, with multiple absolute measurements. Fed-state didanosine values below 20% were discounted as altered conditions, and the provenance-conflicted didanosine record under emtricitabine was excluded. High bioavailability is therefore better supported.",
  "evidence_gaps": [
    "Molecule 6 didanosine fed-state F values (0.17–0.19) are below threshold but were discounted as altered feeding conditions; fasting values are above threshold.",
    "Record C49 under Molecule 9 refers to didanosine rather than emtricitabine and was discounted as a provenance conflict."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

